    g=[row[:] for row in grid]; h,w=len(g),len(g[0])
    W={(r,c) for r in range(h) for c in range(w) if g[r][c]==2}
    changed=True
    while changed:
        changed=False; new=set()
        for (r,c) in W:
            if r+1<h and g[r+1][c]==0: new.add((r+1,c))
            if r+1<h and g[r+1][c]==8:
                for dd in(-1,1):
                    c2=c+dd
                    while 0<=c2<w and g[r][c2]==0:
                        new.add((r,c2))
                        if g[r+1][c2]==0: break
                        c2+=dd
        for p in new:
            if p not in W: W.add(p); g[p[0]][p[1]]=2; changed=True
    return g
