D={'N':(-1,0),'S':(1,0),'E':(0,1),'W':(0,-1)}
PERP={'N':('E','W'),'S':('E','W'),'E':('N','S'),'W':('N','S')}
TURND={'E':'S','W':'S','N':'E','S':'E'}  # sideways spread's "down" side

def streams(grid):
    g=[row[:] for row in grid]; h,w=len(g),len(g[0])
    r0,c0=[(r,c) for r in range(h) for c in range(w) if g[r][c]==2][0]
    dist,grav=min((r0,'S'),(h-1-r0,'N'),(c0,'E'),(w-1-c0,'W'))
    def inside(r,c): return 0<=r<h and 0<=c<w
    def main(r,c,d):
        while True:
            g[r][c]=2
            dr,dc=D[d]; nr,nc=r+dr,c+dc
            if not inside(nr,nc): return          # edge: stop
            if g[nr][nc]==8:                       # wall: spread both sides
                for pd in PERP[d]:
                    pr,pc=D[pd]
                    if inside(r+pr,c+pc) and g[r+pr][c+pc]==0:
                        side(r+pr,c+pc,pd)
                return
            r,c=nr,nc
    def side(r,c,d):
        while True:
            g[r][c]=2
            td=TURND[d]; tr,tc=D[td]
            if inside(r+tr,c+tc) and g[r+tr][c+tc]==0:
                main(r+tr,c+tc,td); return         # turn down through gap, stop
            dr,dc=D[d]; nr,nc=r+dr,c+dc
            if not inside(nr,nc) or g[nr][nc]==8: return
            r,c=nr,nc
    main(r0,c0,grav)
    return g

